/**
 * Create the "Eight roles, not eight hires" blog post in Sanity.
 *
 * Usage:
 *   node scripts/create-eight-roles-post.mjs             (dry run, no writes)
 *   node scripts/create-eight-roles-post.mjs --commit    (write as a DRAFT, invisible on the live site)
 *   node scripts/create-eight-roles-post.mjs --commit --publish   (write as a PUBLISHED post, goes live)
 *
 * Idempotent: deterministic _id, so re-runs update in place.
 * Meta/OG/Twitter/JSON-LD are generated by the blog route from the SEO fields set below.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createClient } from "@sanity/client";

// --- env ---------------------------------------------------------------
function loadEnv() {
  try {
    const raw = readFileSync(resolve(process.cwd(), ".env.local"), "utf8");
    for (const line of raw.split("\n")) {
      const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
      if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
    }
  } catch { /* rely on real env */ }
}
loadEnv();

const COMMIT = process.argv.includes("--commit");
const PUBLISH = process.argv.includes("--publish");

const {
  NEXT_PUBLIC_SANITY_PROJECT_ID: projectId,
  NEXT_PUBLIC_SANITY_DATASET: dataset,
  NEXT_PUBLIC_SANITY_API_VERSION: apiVersion = "2024-10-01",
  SANITY_API_WRITE_TOKEN: token,
} = process.env;

if (!projectId || !dataset) { console.error("Missing project id / dataset in .env.local"); process.exit(1); }
if (COMMIT && !token) { console.error("Missing SANITY_API_WRITE_TOKEN (needed for --commit)"); process.exit(1); }

const sanity = createClient({ projectId, dataset, apiVersion, token, useCdn: false });

// --- portable text helpers --------------------------------------------
let _k = 0;
const key = () => `k${_k++}`;
const span = (text, marks = []) => ({ _type: "span", _key: key(), text, marks });
const block = (style, children, opts = {}) => ({
  _type: "block", _key: key(), style, markDefs: opts.markDefs || [], children,
  ...(opts.listItem ? { listItem: opts.listItem, level: opts.level || 1 } : {}),
});
const p = (c) => block("normal", Array.isArray(c) ? c : [span(c)]);
const h2 = (t) => block("h2", [span(t)]);
const h3 = (t) => block("h3", [span(t)]);
const quote = (t) => block("blockquote", [span(t)]);
const li = (c) => block("normal", Array.isArray(c) ? c : [span(c)], { listItem: "bullet", level: 1 });

// bold lead-in paragraph: "**lead** rest"
const lead = (boldText, rest) => p([span(boldText, ["strong"]), span(rest)]);

// a role block set: h3 + works-like + description + boundary
function role(n, name, character, worklike, desc, boundary, alwaysOn) {
  const heading = `${n}. ${name}, played by ${character}${alwaysOn ? " (always on)" : ""}`;
  return [
    h3(heading),
    lead("Works like ", worklike),
    p(desc),
    lead("The boundary: ", boundary),
  ];
}

// table block (new "table" type in blockContent: rows -> { cells: string[] })
const trow = (cells) => ({ _type: "row", _key: key(), cells });
const table = (header, rows, caption) => ({
  _type: "table", _key: key(), hasHeaderRow: true,
  ...(caption ? { caption } : {}),
  rows: [trow(header), ...rows.map((r) => trow(r))],
});

// --- body --------------------------------------------------------------
const linkKey = "vortexiq-link";
const body = [
  p('Most "AI agent" pitches sell you one clever generalist: a single model that reads, decides, writes, ships, and then reports on itself. It demos beautifully. Then it edits your live store at 2 a.m. on a hunch, and nobody can say which step went wrong, because there were no steps. There was one actor doing everything.'),
  p("Vortex IQ is built the other way round. Instead of one agent that does eight things, the platform runs eight roles that each do one thing, and each one has a boundary it will not cross. These eight roles are the Vortex Agents layer inside Vortex IQ, the AI Operating System for e-commerce: the agentic operations and modernisation layer of the commercial platform. Below is the crew, what each role works like, and the line each one is not allowed to step over."),

  h2("Why roles, not one clever agent"),
  p("The design borrows from how a real operations team stays out of trouble: separation of duties. The person who writes a change is not the person who approves it. The person who approves it is not the tool that applies it. The tool that applies it keeps a receipt. No single actor has the whole chain, so no single mistake, or single bad instruction, can run end to end unchecked."),
  p("Two ideas make that work, and they are worth stating precisely before you meet the crew."),
  quote("A role is fixed. A character is not."),
  p("A role decides the job. The audit log always records the role, never the nickname. A character is the face and name on that role, and you can change both. Rename Scout to anything you like; the log still records that the Scout role did the gathering. The story on screen can be friendly. The record underneath stays exact."),
  lead("The job titles describe the work, not a headcount. ", "When we say a role works like a release engineer, that is the shape of the job, not a claim that you are paying for eight people. These are eight functions that a team of three to five people already performs, named and separated so software can carry them safely. You are not hiring eight agents. You are giving eight jobs a clear owner and a clear boundary."),

  h2("The eight roles"),
  ...role(1, "Lead", "Beacon", "a project manager or delivery lead.",
    "Beacon reads the request, works out which specialists it actually calls for, dispatches only those, and holds the rest back. If a job needs gathering and reporting but no changes, the roles that make and apply changes never wake up.",
    "Beacon never touches a tool itself. It dispatches, and it stops. The lead that also does the work is the lead that skips its own checks.", true),
  ...role(2, "Scout", "Scout", "an SEO auditor or research analyst.",
    "Scout gathers. It pulls from any connected source, your store, your analytics, your search data, your ad accounts, and reports exactly what came back. What you get is the raw truth of what the connectors returned, nothing dressed up.",
    "Scout never writes anything, and never invents what a tool could have fetched. If the data is not there, Scout says so. It does not fill the gap with a good guess."),
  ...role(3, "Analyst", "Iris", "a data or BI analyst.",
    "Iris runs the deterministic engine over what Scout brought back: it filters, extracts, and reshapes. Same input, same output, every time. When Iris tells you a number moved, you can reproduce that number yourself from the same source rows.",
    "Iris never does the maths in its own head. The calculation runs through the engine, not the model, so every figure stays reproducible and nothing is roughly right."),
  ...role(4, "Maker", "Forge", "a developer, designer, or copywriter.",
    "Forge writes the thing. A title, a description, a fix, a summary. Then it hands the work over as a proposal, not a change. What Forge produces is a draft with your name on the approval line, waiting.",
    "Forge never applies, approves, or checks its own work. The role that creates the change is deliberately not the role that judges it. That separation is the whole point."),
  ...role(5, "Runner", "Kai", "a DevOps or release engineer.",
    "Kai applies what you approved, and can roll it back byte for byte. Fixes run on a staging snapshot by default, with zero live writes; live writes go to the real store only through the platform admin connector, and only where you have opened the gate. Every change is captured and exactly reversible, proven live on Shopify and BigCommerce.",
    "Kai never acts without an approval, and never decides what should change. It is hands, not judgment: exactly what was signed off, plus the receipt that lets you undo it."),
  ...role(6, "Checker", "Lens", "QA, code review, security, or accessibility.",
    "Lens flags the findings that must never be changed automatically, and holds them for a person to judge. Some things are too sensitive to touch on a machine's say-so, and Lens is the role that knows the difference and refuses to let them through the automatic lane.",
    "Lens never fixes what it finds, and never checks work it produced. A reviewer that can also edit is not a reviewer."),
  ...role(7, "Reporter", "Memo", "an account manager or technical writer.",
    "Memo records what happened and tells people, short and factual, with the real numbers. When you come back, Memo is the one that says what was audited, what was proposed, what you approved, and what changed, in plain language.",
    "Memo never acts on the store, and never announces work that did not happen. The report matches the record. If it was not done, Memo does not say it was."),
  ...role(8, "Pulse", "Pulse", "a site reliability engineer.",
    "Pulse proves the connectors actually work, on a heartbeat. It health-checks connections before they break, retries transient failures with a backoff ladder, auto-pauses what it cannot fix (always with a plain reason and a Fix and resume button), and interrupts you only when something genuinely needs a decision.",
    "Pulse never nags. A healthy heartbeat says nothing at all. It alerts one trusted channel, never inside quiet hours, and never twice for the same problem. Silence from Pulse is the good outcome.", true),

  h2("The cast: one role, played across many jobs"),
  p("A character carries its role from one scenario to the next. Scout audits your store today and researches your AI visibility tomorrow; it is the same Scout role doing the gathering in both. This is where role is fixed, character is not earns its keep: a familiar cast across every workflow, and an audit trail that does not care what you named them."),
  p("Here is who plays what, and where. A lock marks scenarios in the paid Vortex IQ plans."),
  table(
    ["Character", "Plays", "Appears in"],
    [
      ["Beacon", "Lead", "Audit and findings, Store migration 🔒"],
      ["Scout", "Scout", "Audit and findings, SEO and AI visibility 🔒"],
      ["Iris", "Analyst", "SEO and AI visibility 🔒, Ask Viq 🔒, Insight reports 🔒, Live monitoring, Ad spend 🔒"],
      ["Forge", "Maker", "Fixes, SEO and AI visibility 🔒, Ad spend 🔒"],
      ["Kai", "Runner", "Fixes, Ask Viq 🔒, Store migration 🔒, Live monitoring"],
      ["Lens", "Checker", "Audit and findings, Store migration 🔒"],
      ["Memo", "Reporter", "Audit and findings, Fixes, Ask Viq 🔒, Insight reports 🔒, Memory"],
      ["Pulse", "Pulse", "Insight reports 🔒, Live monitoring, Ad spend 🔒"],
    ],
    "The cast: which character plays which role, and where each appears."
  ),

  h2("Why this is the safe way to run agents on a live store"),
  p("Put the boundaries side by side and a single rule falls out of them: no role both makes a change and blesses it."),
  li([span("Scout", ["strong"]), span(" gathers but cannot write.")]),
  li([span("Iris", ["strong"]), span(" calculates but through the engine, not by feel.")]),
  li([span("Forge", ["strong"]), span(" proposes but cannot apply.")]),
  li([span("Lens", ["strong"]), span(" reviews but cannot edit.")]),
  li([span("Kai", ["strong"]), span(" applies but only what you approved, and can always undo it.")]),
  li([span("Memo", ["strong"]), span(" reports but only what actually happened.")]),
  li([span("Beacon", ["strong"]), span(" directs but never touches a tool.")]),
  li([span("Pulse", ["strong"]), span(" watches but stays quiet unless a human decision is needed.")]),
  p('That is what "agentic" should mean on a store you actually depend on: not one model trusted with everything, but a crew of narrow specialists, a person on the approval line for anything that writes, and a record that names the role behind every step. Detect. Explain. Fix. In that order, with a boundary between each one.'),

  h2("How this fits the rest of Vortex IQ"),
  p("The crew is the Vortex Agents layer, and it works alongside the rest of the AI Operating System: Nerve Centre watching your store and connectors in real time, Vortex Mind explaining what it finds, and Vortex Apps staging every change as a diff you approve and can reverse. So a silent failure reaches you before it reaches a customer, and nothing touches your store without a person on the approval line."),
  p("Eight roles, eight boundaries, and one honest record of what each of them did while you were away. That is the shape of agentic operations we think a store can actually trust."),
  block("normal", [
    span("Vortex IQ is the AI Operating System for e-commerce. See how it works at "),
    span("vortexiq.ai", [linkKey]),
    span("."),
  ], { markDefs: [{ _type: "link", _key: linkKey, href: "https://www.vortexiq.ai" }] }),
];

// --- document ----------------------------------------------------------
const slug = "eight-roles-not-eight-hires";
const baseId = `post-${slug}`;
const docId = PUBLISH ? baseId : `drafts.${baseId}`;

const doc = {
  _id: docId,
  _type: "post",
  title: "Eight roles, not eight hires: the crew inside Vortex IQ",
  slug: { _type: "slug", current: slug },
  excerpt:
    "Most AI agent pitches sell you one clever generalist. Vortex IQ runs eight roles instead: one job each, one hard boundary each, and an audit log that records the role every time.",
  publishedAt: new Date().toISOString(),
  category: { _type: "reference", _ref: "category-the-agentic-shift" },
  author: { _type: "reference", _ref: "author-susant-patro" },
  // SEO -> the blog route turns these into <title>, meta description, canonical, OG + Twitter, JSON-LD
  seoTitle: "Eight roles, not eight hires",
  seoDescription:
    "Vortex IQ runs eight specialist AI agents, one job each and one hard boundary each, so nothing changes your store without a person on the approval line.",
  body,
};

console.log(`\n${COMMIT ? (PUBLISH ? "⚙️  COMMIT + PUBLISH (goes LIVE)" : "⚙️  COMMIT as DRAFT (not public)") : "🔍 DRY RUN (no writes)"}`);
console.log(`  project=${projectId} dataset=${dataset}`);
console.log(`  _id=${docId}`);
console.log(`  slug=/resources/blog/${slug}`);
console.log(`  body blocks=${body.length}`);
console.log(`  seoTitle="${doc.seoTitle}"  (renders "${doc.seoTitle} · Vortex IQ")`);
console.log(`  seoDescription (${doc.seoDescription.length} chars)="${doc.seoDescription}"`);

if (process.argv.includes("--ndjson")) {
  const { writeFileSync } = await import("node:fs");
  const out = resolve(process.cwd(), "eight-roles-post.ndjson");
  writeFileSync(out, JSON.stringify(doc) + "\n", "utf8");
  console.log(`\n✓ Wrote import file: ${out}`);
  console.log("  Import with your own logged-in Sanity CLI (no token needed):");
  console.log(`    npx sanity dataset import eight-roles-post.ndjson ${dataset} --replace`);
  console.log("  The _id is a draft, so it imports as a draft to review in Studio, then Publish.\n");
  process.exit(0);
}

if (!COMMIT) {
  console.log("\nDry run only. Re-run with --commit (draft) or --commit --publish (live).");
  console.log("No write token? Use --ndjson to emit an import file for your Sanity CLI.\n");
  process.exit(0);
}

sanity.createOrReplace(doc)
  .then(() => {
    console.log(`\n✓ Written: ${docId}`);
    if (PUBLISH) console.log("  It is a PUBLISHED post. It will appear at /resources/blog within ~60s (ISR) or the next build.");
    else console.log("  It is a DRAFT. Open Sanity Studio, review, and hit Publish to take it live. It is not public yet.");
    console.log("");
  })
  .catch((err) => { console.error("\n✗ Write failed:", err.message); process.exit(1); });
